			Predicate n4 = cb.equal(b.get("effectiveDateEnd"), effectiveDate5);
			Predicate n5 = cb.equal(b.get("countryId"), req.getCountryId());
			query.where(n1,n2,n3,n4,n5).orderBy(orderList);
	
